using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Xml.Serialization;using MakroSoundSwitch;
class ChordVerify {
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS: "+message);}
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 var legacy=new Scenario{Modifiers=8,Key=123};Assert(Chords.KeysFor(legacy).SequenceEqual(new[]{91,123}),"Existing Windows + F12 shortcut migrates without editing");Assert(Chords.Display(legacy)=="Windows + F12","Legacy shortcut label remains readable");
 var target=new HashSet<int>(new[]{17,18,16,75,76});int fired=0;var tracker=new ChordTracker{Trigger=keys=>{if(keys.SetEquals(target)){fired++;return true;}return false;}};var physical=new HashSet<int>();foreach(int key in new[]{75,17,76,18,16}){bool swallowed=tracker.Process(key,true,physical);if(key!=16)physical.Add(key);Assert(swallowed==(key==16),"Chord waits for final key (key "+key+")");}Assert(fired==1,"Five-key chord fires in arbitrary press order");Assert(tracker.Process(16,true,physical)&&fired==1,"Autorepeat is consumed without firing again");Assert(tracker.Process(16,false,physical),"Consumed key release is paired with consumed press");Assert(tracker.Process(16,true,physical)&&fired==2,"Releasing and repressing a key reactivates shortcut");
 var extra=new ChordTracker{Trigger=keys=>keys.SetEquals(target)};Assert(!extra.Process(76,true,new[]{17,18,16,75,65}),"Extra unrelated keys prevent unintended activation");Assert(Chords.Conflict(new[]{91,123},new[]{91,17,123}),"Subset shortcuts rejected to avoid premature activation");Assert(!Chords.Conflict(new[]{91,123},new[]{17,18,16,75,76}),"Distinct chords remain available");Assert(Chords.Normalize(163)==17&&Chords.Normalize(161)==16&&Chords.Normalize(165)==18&&Chords.Normalize(92)==91,"Left and right modifier keys match consistently");
 var scenario=new Scenario{Name="Five key setup",Chord=new List<int>{17,18,16,75,76}};var serializer=new XmlSerializer(typeof(Scenario));using(var stream=new MemoryStream()){serializer.Serialize(stream,scenario);stream.Position=0;Assert(Chords.KeysFor((Scenario)serializer.Deserialize(stream)).SequenceEqual(scenario.Chord),"Five-key shortcuts survive XML save and reload");}
 using(var editor=new Editor(scenario,new List<Scenario>{scenario})){editor.Show();Application.DoEvents();var selectors=(List<ComboBox>)typeof(Editor).GetField("keySelectors",F).GetValue(editor);Assert(selectors.Count==5,"Editor displays five individual key dropdowns");var rows=(Control)typeof(Editor).GetField("keyRows",F).GetValue(editor);Assert(rows.Height>=195&&rows.Visible,"Five-key selector area is visible");typeof(Editor).GetMethod("AddKey",F).Invoke(editor,new object[]{77});Application.DoEvents();Assert(selectors.Count==6,"Add key extends shortcut beyond five keys");var row=rows.Controls[5];row.Controls.OfType<Button>().Single().PerformClick();Application.DoEvents();Assert(selectors.Count==5,"Remove button removes one selected key");using(var b=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(b,new Rectangle(Point.Empty,editor.Size));b.Save("five-key-editor.png");}editor.Close();}
 }
}


